<script setup lang="ts">
import {computed,ref} from 'vue';import {ui,request,sendEcho} from '../state/device';import {t} from '../state/appearance';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';
const value=ref('Привет, NaWServer!'),method=ref('GET'),result=ref(''),status=ref('—'),busy=ref(false),wsText=ref('hello from observatory'),wsType=ref('text');const entries=computed(()=>ui.wsLog.slice().reverse());
async function echo(){busy.value=true;const started=performance.now();try{const data=new URLSearchParams({value:value.value});const r=await request('/api/v2/echo'+(method.value==='GET'?'?'+data:''),method.value==='POST'?{method:'POST',body:data}:{});result.value=r.text;status.value=`${r.status} · ${Math.round(performance.now()-started)} ms`;}catch(e){result.value=String(e);status.value='ERROR'}finally{busy.value=false}}
async function buffered(){const r=await request('/api/v2/stream');result.value=r.text;status.value=String(r.status)}
</script>
<template><div class="two-panels"><section class="panel"><div class="panel-head"><h2><Icon name="arrows-exchange"/>HTTP / {{t('Запрос и ответ','Request and response')}}</h2><InfoButton label="HTTP" help-key="http"/></div><form @submit.prevent="echo"><label class="label" for="http-input">{{t('Значение query / form','Query / form value')}}</label><div class="input-row"><select v-model="method" :aria-label="t('HTTP метод','HTTP method')"><option>GET</option><option>POST</option></select><input id="http-input" v-model="value" maxlength="512"><button class="primary" :disabled="busy"><Icon name="arrow-right"/>{{t('Отправить','Send')}}</button></div></form><p class="endpoint">/api/v2/echo</p><div class="result-head"><span>RESPONSE</span><span>{{status}}</span></div><pre class="terminal" data-testid="http-result">{{result||t('Ожидание запроса','Waiting for a request')}}</pre><div class="inline-actions"><button @click="buffered">{{t('Буферизованный ответ','Buffered response')}}</button><a href="/go">Redirect</a></div></section><section class="panel"><div class="panel-head"><h2><Icon name="arrows-exchange"/>WebSocket / CBOR</h2><span class="pill">{{ui.wsOnline?'ONLINE':'OFFLINE'}}</span></div><form @submit.prevent="sendEcho(wsText,wsType==='binary')"><label class="label" for="ws-input">{{t('Публичный /ws · echo','Public /ws · echo')}}</label><div class="input-row"><select v-model="wsType" :aria-label="t('Тип WS','WS payload')"><option value="text">CBOR · text</option><option value="binary">CBOR · bytes</option></select><input id="ws-input" v-model="wsText" maxlength="512"><button class="primary" :disabled="!ui.wsOnline">Echo</button></div></form><div class="result-head"><span>FRAMES / {{ui.wsLog.length}}</span><button class="text-button" @click="ui.wsLog=[]">{{t('Очистить','Clear')}}</button></div><div class="terminal frame-log" role="log"><div v-for="e in entries" :key="e.id"><span>{{e.time}}</span> {{e.message}}</div></div></section></div></template>
